"""Final-command safety: the Milestone 1 SafetyEvaluator/SafetyGate applied to the OUTGOING velocity, with
the free distance taken from the map in the commanded direction (lateral protection: the march uses the
body-inflated distance field, and UNKNOWN counts as blocked, so moving sideways or backwards out of the
camera's view is limited by remembered obstacles or stopped by unknown space), combined with the
depth-corridor distance when the direction is inside the camera's view, and a vertical guard (flight
band + the organizer interface's 0.3-3.0 m) that removes any climb or descent leaving the band.

Fails closed: stale depth or odometry, unknown localization or a missing map give 0 m/s.
"""
from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Optional, Tuple

import numpy as np

from ..safety_filter import SafetyEvaluator, SafetyGate, SafetyParams, SensorInputs, Verdict


class _Inert:
    speed_scale = 1.0
    traj = None


@dataclass
class CommandSafetyParams:
    safety: SafetyParams = field(default_factory=lambda: SafetyParams(v_max=0.8))
    band: Tuple[float, float] = (0.5, 1.0)
    alt_limits: Tuple[float, float] = (0.3, 3.0)    # organizer flight_interface clamp
    v_iface_max: float = 1.5                        # organizer twist cap
    robot_radius: float = 0.27
    hard_radius: Optional[float] = 0.28            # last-line body clearance (physical 0.24 + 4 cm); the planner keeps
                                                   # the larger robot_radius (+2 sigma pose). None = robot_radius
    march_max: float = 3.0
    yaw_in_place_ok: bool = True                    # rotating in place is allowed at a wall if data are valid
    hold_vz: float = 0.05                           # vertical speed still counted as "holding" during a rotation
    geofence: Optional[Tuple[float, float, float, float]] = None   # xmin xmax ymin ymax (ENU odom); None = refuse
    geofence_margin: float = 0.4                    # keep the body centre this far inside (netting may not show in depth)


class CommandSafety:
    def __init__(self, prm: CommandSafetyParams = CommandSafetyParams()):
        self.prm = prm
        self.gate = SafetyGate(_Inert(), SafetyEvaluator(prm.safety))

    def map_free_distance(self, dist, grid, pos, dir_xy) -> float:
        """Distance the body centre can move along dir before the inflated body meets OCCUPIED or UNKNOWN.
        If it already overlaps, only motion that does not get closer is allowed."""
        r = self.prm.hard_radius if self.prm.hard_radius is not None else self.prm.robot_radius
        res = grid.res

        def d_at(q):
            rr, cc = grid.to_cell(q)
            return float(dist[rr, cc])
        d0 = d_at(pos)
        step = 0.5 * res
        s = 0.0
        while s < self.prm.march_max:
            q = pos[:2] + (s + step) * dir_xy
            dq = d_at(q)
            if (d0 >= r and dq < r) or (d0 < r and dq < d0 - 0.02):
                break
            s += step
        return s

    def filter(self, v_cmd, yaw_rate, pos, now, dist, grid, odom_stamp, odom_rx, depth_stamp, depth_rx,
               loc_mode, depth_corridor_free: Optional[float] = None, pos_std: Optional[float] = None):
        p = self.prm
        v = np.asarray(v_cmd, float).copy()
        if v.shape != (3,) or not np.all(np.isfinite(v)) or not math.isfinite(yaw_rate):
            return np.zeros(3), 0.0, Verdict("UNKNOWN", 0.0, "COMMAND_INVALID")
        # vertical guard: never leave the band (no climbing over walls) nor the interface limits
        z_lo, z_hi = max(p.band[0], p.alt_limits[0]), min(p.band[1], p.alt_limits[1])
        if (pos[2] >= z_hi and v[2] > 0) or (pos[2] <= z_lo and v[2] < 0):
            v[2] = 0.0
        # geofence: unset = no horizontal motion at all; at the margin, no motion further out
        if p.geofence is None:
            v[0] = v[1] = 0.0
        else:
            x0, x1, y0, y1 = p.geofence
            m = p.geofence_margin
            if (pos[0] <= x0 + m and v[0] < 0) or (pos[0] >= x1 - m and v[0] > 0):
                v[0] = 0.0
            if (pos[1] <= y0 + m and v[1] < 0) or (pos[1] >= y1 - m and v[1] > 0):
                v[1] = 0.0
        vh = math.hypot(v[0], v[1])
        if dist is None or grid is None:
            free = None
        elif vh > 1e-3:
            free = self.map_free_distance(dist, grid, pos, v[:2] / vh) + p.safety.vehicle_radius
        else:
            free = self.map_free_distance(dist, grid, pos, np.array([1.0, 0.0])) + p.safety.vehicle_radius
        if free is not None and depth_corridor_free is not None:
            free = min(free, depth_corridor_free)
        inp = SensorInputs(now=now, free_distance=free, depth_stamp=depth_stamp, depth_rx=depth_rx,
                           odom_stamp=odom_stamp, odom_rx=odom_rx, pos_std=pos_std, transform_valid=True,
                           loc_mode=loc_mode)
        if p.yaw_in_place_ok and vh < 1e-3 and abs(v[2]) <= p.hold_vz:
            # pure rotation needs no clearance (the body is treated as radially symmetric), but it still needs
            # fresh data and valid localization: judge only those (no map is required, e.g. at start-up)
            inp.free_distance = p.safety.reliable_range
            verdict = self.gate.update(inp, 0.0)
            ok = verdict.verdict in ("SAFE", "LIMIT") or verdict.reason == "NO_STOPPING_ROOM"
            out = np.array([0.0, 0.0, v[2]]) if ok else np.zeros(3)     # altitude hold stays inside the band guard
            return out, (float(yaw_rate) if ok else 0.0), verdict
        verdict = self.gate.update(inp, float(math.hypot(vh, v[2])))
        v_out, yaw_out = self.gate.clamp(v, yaw_rate)
        n = float(np.linalg.norm(v_out))
        if n > p.v_iface_max:
            v_out *= p.v_iface_max / n
        return v_out, yaw_out, verdict
